name VARCHAR(255) NOT NULL NOT NULL,
api_key_hash VARCHAR(255) NOT NULL NOT NULL,
status VARCHAR(50) DEFAULT 'active' NOT NULL,
events_per_sec INTEGER DEFAULT 1200 NOT NULL
);


