event_type VARCHAR(100) NOT NULL NOT NULL,
payload_json TEXT NOT NULL NOT NULL,
timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
ip_address VARCHAR(45) NOT NULL
);
